import json,pathlib,re,html,shutil,os
root=pathlib.Path(__file__).resolve().parents[1];os.chdir(root)
d=json.loads(pathlib.Path('assets/data.js').read_text().removeprefix('window.SITE_DATA = ').rstrip(';\n'));E=html.escape
styles='<link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="manifest" href="/manifest.webmanifest"><link rel="apple-touch-icon" href="/assets/app/icon-180.png"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="Utah Guide"><link rel="stylesheet" href="/assets/styles.css"><link rel="stylesheet" href="/assets/date-tools.css"><link rel="stylesheet" href="/assets/seasonal.css">'
nav='<header class="site-header"><div class="nav-wrap"><a class="brand" href="/">UTAH <b>SEASONAL</b> GUIDE</a><nav class="nav" aria-label="Primary navigation"><a data-nav="explore" href="/">Explore</a><a data-nav="weekend" href="/weekend/">This weekend</a><a data-nav="vibes" href="/vibes/">Find your vibe</a><a data-nav="saved" href="/saved/">My saved events <span class="saved-count" data-saved-count>0</span></a><a class="submit-link" data-nav="submit" href="/submit/">Suggest an event</a></nav></div></header>'
footer='<footer class="site-footer"><div class="footer-inner"><div><b>Utah Seasonal Guide</b><br>Fall & winter 2026–27 · Updated October 6, 2026</div><div><a href="/about/">About & accessibility</a><br><a href="/contact/">Contact & sponsorships</a><br><a href="/terms/">Terms</a> · <a href="/privacy/">Privacy</a><br><a href="/image-credits/">Image credits</a></div><div><a href="/submit/">Suggest an event or correction</a><br><a href="/saved/">My saved events</a><br><a href="/app/">Add the guide to your home screen</a></div></div></footer>'
# Existing social symbols are local, decorative and compatible with screen readers.
original=pathlib.Path('index.html').read_text();icons=re.search(r'<svg class="icon-defs".*?</svg>',original,re.S).group(0)
scripts='<script src="/assets/data.js"></script><script src="/assets/date-tools.js"></script><script src="/assets/site.js"></script><script src="/assets/event-enhancements.js"></script><script src="/assets/app.js"></script>'
base='https://chipper-froyo-598c2e.netlify.app'
def page(title,body,page='explore',desc='Find Utah holiday celebrations, light displays, live shows, markets, community events and seasonal experiences.',extra='',scripts_extra=''):
 return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#19201d"><title>{E(title)} | Utah Seasonal Guide</title><meta name="description" content="{E(desc,quote=True)}">{styles}{extra}</head><body data-page="{page}" data-theme="winter"><a class="skip" href="#main">Skip to main content</a>{icons}{nav}{body}{footer}{scripts}{scripts_extra}</body></html>\n'
def options(items):return ''.join(f'<option value="{E(str(k),quote=True)}">{E(str(v))}</option>' for k,v in items)
index='''<section class="hero"><div class="hero-inner"><div><div class="eyebrow" id="heroEyebrow">Fall & winter 2026–27</div><h1 id="heroTitle">Your next good reason to get out.</h1><p id="heroDescription">Discover Utah’s seasonal celebrations, local traditions, shows and wonderfully unexpected things to do.</p><div class="hero-stats"><div class="stat"><b id="stat-events"></b><span>ideas to explore</span></div><div class="stat"><b id="stat-confirmed"></b><span>announced events</span></div><div class="stat"><b id="stat-regions"></b><span>Utah regions</span></div></div></div><div class="hero-art"><img id="heroArt" src="/assets/art/seasonal/winter-community.svg" width="1600" height="900" alt=""></div></div></section>
<main id="main" tabindex="-1"><div class="page-head"><div class="season-chip" id="seasonLabel">All celebrations · 2026–27</div><h2>Find your kind of celebration.</h2><p>Pick a holiday, then narrow it down by date, place and what you feel like doing.</p></div><nav id="seasonPicker" class="season-picker" aria-label="Choose a holiday"></nav><div class="quick-picks"><a href="/?when=weekend">This weekend</a><a href="/?when=tonight">Tonight</a><a href="/?free=1">Free admission</a><a href="/?community=LGBTQ%2B">Queer community</a><a href="/?category=Giving+%26+Volunteering">Give a little back</a></div><section id="sponsoredEvents" class="sponsored-events" aria-label="Sponsored advertisements" hidden></section><section class="controls compact-controls" aria-label="Event filters"><div class="search-row"><label class="sr-only" for="search">Search events, cities or activities</label><input id="search" class="search" type="search" placeholder="Search an event, city or activity"><button id="favoritesOnly" class="btn-filter" type="button" aria-pressed="false">☆ Saved events</button></div><div class="primary-filter-grid"><label class="filter-control"><span>When</span><select id="whenFilter">WHEN</select></label><label class="filter-control"><span>Where</span><select id="regionFilter"><option value="">All regions</option></select></label><label class="filter-control"><span>What</span><select id="categoryFilter"><option value="">All activities</option></select></label><details id="moreFilters" class="more-filters"><summary>More filters <span id="moreFilterCount" class="filter-count" hidden></span></summary><div class="more-filter-grid"><label class="filter-control"><span>Audience</span><select id="ageFilter"><option value="">Any audience</option></select></label><label class="filter-control"><span>Price</span><select id="costFilter">COST</select></label><label class="filter-control"><span>Scare level</span><select id="scareFilter">SCARE</select></label><label class="filter-control"><span>Good to know</span><select id="flagFilter"><option value="">Any practical details</option></select></label><label class="filter-control"><span>Community / tradition</span><select id="communityFilter"><option value="">Any community</option></select></label><label class="check-filter"><input id="freeOnly" type="checkbox">Free admission only</label><label class="check-filter"><input id="includeWatch" type="checkbox">Include announcements pending</label><label class="filter-control"><span>Sort</span><select id="sortFilter"><option value="date">Next available date</option><option value="name">A–Z</option><option value="cost">Lowest cost first</option></select></label></div></details></div><div id="customDateWrap" class="custom-date-wrap" hidden><label class="filter-control"><span>Choose a date</span><input type="date" id="datePick" min="2026-09-01" max="2027-03-31"></label></div><div class="active-filter-row"><div id="activeFilters" role="group" class="active-filters" aria-label="Active filters"></div><button id="clearFilters" class="clear-all" type="button" hidden>Clear all</button></div><p class="search-hint">Tonight and Open now use confirmed evening hours, in Utah time. Free admission may still have optional purchases or parking costs.</p></section><div class="resultsbar" role="status" aria-live="polite"><div><strong id="resultCount"></strong> matches</div><div id="filterSummary"></div></div><section id="eventCards" class="cards" aria-label="Events"></section><button id="loadMore" class="loadmore" type="button">Show more events</button><noscript><p>Use an event’s page to plan your visit. Interactive search needs JavaScript.</p><ul>NOJS</ul></noscript></main>'''
index=index.replace('WHEN',options([('','Any date'),('today','Today'),('tonight','Tonight'),('open-now','Open now'),('tomorrow','Tomorrow'),('weekend','This weekend'),('next-weekend','Next weekend'),('date','Pick a date…')])).replace('COST',options([('','Any price'),(1,'Free / very low'),(2,'Up to $25'),(3,'$26–50'),(4,'$51–100'),(5,'Over $100'),(0,'Price not announced')])).replace('SCARE',options([('','Any scare level'),(1,'1 · Gentle'),(2,'2 · Light'),(3,'3 · Moderate'),(4,'4 · Scary'),(5,'5 · Extreme')])).replace('NOJS',''.join(f'<li><a href="/events/{e["id"]}/">{E(e["Event / attraction"])}</a></li>' for e in d['events'] if not e['isWatch']))
pathlib.Path('index.html').write_text(page('Utah holiday events & seasonal adventures',index,extra=f'<link rel="canonical" href="{base}/">'))
# Short public copy focuses on visitors, not research procedures.
about=pathlib.Path('scripts/page-templates/about.html').read_text()
pathlib.Path('about.html').write_text(page('About the guide',about,'about'))
for name,pg,title,desc,host in [('weekend','weekend','Your weekend, your way.','Find events happening this Friday through Sunday.','planner'),('itineraries','routes','Make a day of it.','Pair an experience with food, a stroll or something unexpected nearby.','routes'),('vibes','vibes','What sounds good today?','Start with a mood, then find a celebration that fits.','vibesGrid'),('standouts','standouts','A few good places to start.','A mix of immersive spectacles, local traditions and thoughtful experiences.','standoutsGrid')]:
 body=f'<main id="main" tabindex="-1"><div class="page-head"><h1>{title}</h1><p>{desc}</p></div><div class="quick-picks"><a href="/?when=weekend">Browse this weekend</a><a href="/?free=1">Free admission</a><a href="/saved/">My saved events</a></div><section id="{host}" class="vibe-grid"></section></main>'
 pathlib.Path(name+'.html').write_text(page(title,body,pg))
pathlib.Path('image-credits.html').write_text(page('Image credits','<main id="main" tabindex="-1"><div class="page-head"><h1>Image credits</h1><p>Photos from the events and places featured in this guide. Illustrated cards use original seasonal icon artwork.</p></div><div id="imageCredits" class="vibe-grid"></div></main>','credits'))
# Static forms are detected by Netlify; confirmation requires a successful response.
form=pathlib.Path('scripts/page-templates/submit.html').read_text()
pathlib.Path('submit.html').write_text(page('Suggest an event or correction',form,'submit',scripts_extra='<script src="/assets/submission.js"></script>'))
pathlib.Path('thanks.html').write_text(page('Message received','<main id="main" tabindex="-1"><h1>Message received.</h1><p>Thanks for helping the guide. Event suggestions are reviewed before publication.</p><a class="button primary" href="/">Back to exploring</a></main>','thanks'))
for name,title in [('saved','My saved events'),('app','Keep the guide handy'),('contact','Contact & sponsorships'),('terms','Terms and conditions'),('privacy','Privacy'),('offline','You’re offline')]:
 body=pathlib.Path('scripts/page-templates/'+name+'.html').read_text()
 pathlib.Path(name+'.html').write_text(page(title,body,name,scripts_extra='<script src="/assets/submission.js"></script>' if name=='contact' else ''))
# Real files for human-friendly URLs, with HTML compatibility redirects.
paths=['about','weekend','itineraries','vibes','standouts','submit','thanks','image-credits','saved','app','contact','terms','privacy','offline'];redirects=[]
for name in paths:
 out=pathlib.Path(name);out.mkdir(exist_ok=True);s=pathlib.Path(name+'.html').read_text().replace('</head>',f'<link rel="canonical" href="{base}/{name}/"></head>');(out/'index.html').write_text(s);redirects.append(f'/{name}.html /{name}/ 301')
pathlib.Path('event.html').write_text(page('Event details','<main id="main" tabindex="-1"><section id="eventDetail"></section></main>','event',scripts_extra='<script>const id=new URLSearchParams(location.search).get("id");if(id&&window.SITE_DATA.events.some(e=>e.id===id))location.replace("/events/"+encodeURIComponent(id)+"/");</script>'))
out=pathlib.Path('events');shutil.rmtree(out,ignore_errors=True);out.mkdir()
urls=[base+'/']+[base+'/'+n+'/' for n in paths if n not in ['thanks','offline']]
for e in d['events']:
 slug=e['id'];o=out/slug;o.mkdir();title=e['Event / attraction'];desc=e['Why / thoughts'][:155];canonical=base+'/events/'+slug+'/'
 fallback=f'<h1>{E(title)}</h1><p>{E(e["2026 schedule"])}</p><p>{E(e["Location"])}</p><p>{E(e["Price"])}</p><p>{E(e["Why / thoughts"])}</p><a href="{E(e["Website"],quote=True)}">Organizer’s event page</a>'
 extra=f'<link rel="canonical" href="{canonical}"><meta property="og:title" content="{E(title,quote=True)}"><meta property="og:description" content="{E(desc,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{base}/assets/share/{e.get("theme","winter")}.png">'
 if not e['isWatch'] and e.get('occurrenceDates'):
  ld={'@context':'https://schema.org','@type':'Event','name':title,'description':e['Why / thoughts'],'url':canonical,'startDate':e['occurrenceDates'][0],'eventStatus':'https://schema.org/EventScheduled','location':{'@type':'Place','name':e['Location']}};extra+='<script type="application/ld+json">'+json.dumps(ld,ensure_ascii=False).replace('</','<\/')+'</script>'
 body=f'<main id="main" tabindex="-1"><section id="eventDetail">{fallback}</section></main>'
 text=page(title,body,'event',desc,extra=extra).replace('<script src="/assets/data.js">',f'<script>window.EVENT_ID={json.dumps(slug)};</script><script src="/assets/data.js">');(o/'index.html').write_text(text)
 if not e['isWatch']:urls.append(canonical)
pathlib.Path('_redirects').write_text('\n'.join(redirects)+'\n')
pathlib.Path('sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'<url><loc>{E(u)}</loc></url>\n' for u in urls)+'</urlset>\n')
pathlib.Path('robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+base+'/sitemap.xml\n')
print('Generated',len(d['events']),'event pages and',len(urls),'sitemap entries')
